refentry.refsect1:
&reftitle.description;
publicYaf_Route_Map::__construct boolcontroller_preferfalse stringdelimiter''
Constrói uma rota de mapeamento. Uma rota de mapeamento mapeia todo o URI para um nome de controlador ou de ação.

  &reftitle.examples;

   Exemplo de Yaf_Route_Map


<?php
/**
 * Adiciona uma rota de mapeamento à pilha de rotas de Yaf_Router
 */
Yaf_Dispatcher::getInstance()->getRouter()->addRoute("name",
    new Yaf_Route_Map());
?>


   &example.outputs.similar;


/* para http://yourdomain.com/product/foo/bar
 * a requisição conterá os seguintes valores:
 */
array(
  "action" => "product_foo_bar",
)




   Exemplo de Yaf_Route_Map


<?php
/**
 * Adiciona uma rota de mapeamento com um delimitador à pilha de rotas de Yaf_Router
 */
Yaf_Dispatcher::getInstance()->getRouter()->addRoute("name",
    new Yaf_Route_Map(true, "_"));
?>


   &example.outputs.similar;


/* para http://yourdomain.com/user/list/_/foo/22
 * a requisição conterá os seguintes valores:
 */
array(
    "controller" => "User_List",
)

/**
 * e parâmetros da requisição:
 */
array(
  "foo" => "22",
)




   Exemplo de Yaf_Route_Map


<?php
/**
 * Adiciona uma rota de mapeamento à pilha de rotas chamando addConfig
 */
$config = array(
    "name" => array(
       "type"             => "map", // Rota Yaf_Route_Map
       "controllerPrefer" => FALSE,
       "delimiter"        => "#!",
    ),
);
Yaf_Dispatcher::getInstance()->getRouter()->addConfig(
    new Yaf_Config_Simple($config));
?>
